import { Component } from '@angular/core';

// ❌ OLD: Without strict templates, the compiler does NOT verify that
// user.nmae exists. The template compiles, the app runs, and the
// binding renders 'undefined' — or throws in a strict null context.
@Component({
  selector: 'app-root',
  template: `
    <p>{{ user.nmae }}</p> <!-- ❌ OLD: no build error for the typo -->
    <button (click)="save($event)">Save</button>
  `,
})
export class AppComponent {
  user = { name: 'Ada' }; // ❌ OLD: typo is only caught when it renders

  save(e: MouseEvent) {}
}

import { Component } from '@angular/core';

// ✅ NEW: With strictTemplates, the compiler generates a type-check
// block that TypeScript verifies. A typo like user.nmae now fails the
// build with a precise error, and event handlers are signature-checked.
@Component({
  selector: 'app-root',
  template: `
    <p>{{ user.name }}</p> <!-- ✅ NEW: checked against the type of user -->
    <button (click)="save($event)">Save</button> <!-- $event inferred as MouseEvent -->
  `,
})
export class AppComponent {
  user = { name: 'Ada' }; // ✅ NEW: template bindings are type-safe

  save(e: MouseEvent) {}
}

